import random
import copy
import json
import collections
from automa.core.game import TO_PLAY, TURN, PLY, UNKNOWN, LABEL, Viewer

NAME = "sushigo"
PLAYERS = ("automa", "human")
SUPPORTED_OPS = [
    'score_flat', 'multiply_next', 'score_majority', 
    'score_tiered', 'score_per_set', 'score_at_end', 'set_flag'
]

CATEGORIES = {
    'salmon_nigiri': ['nigiri'],
    'squid_nigiri': ['nigiri'],
    'egg_nigiri': ['nigiri'],
    'maki_1': ['maki'],
    'maki_2': ['maki'],
    'maki_3': ['maki'],
}

def get_maki_icons(card: str) -> int:
    if card == 'maki_1': return 1
    if card == 'maki_2': return 2
    if card == 'maki_3': return 3
    return 0

def is_chopsticks(card: str, catalog: dict) -> bool:
    for eff in catalog['effects'].get(card, []):
        if eff.get('op') == 'set_flag' and eff.get('flag') == 'chopsticks':
            return True
    return False

def is_kept_for_end(card_type: str, catalog: dict) -> bool:
    for eff in catalog['effects'].get(card_type, []):
        if eff.get('op') == 'score_at_end':
            return True
    return False

def check_unknowns(state: dict) -> dict:
    # Only check revealed cards to avoid triggering the 8-answer engine limit
    # Cards in hand are face-down and their effects are queried when played.
    for p in PLAYERS:
        for area in ['tableaux', 'puddings']:
            for card in state[area][p]:
                if card not in state['catalog']['effects'] and card not in state['catalog']['described']:
                    state[UNKNOWN] = {
                        "kind": "card_effect",
                        "card_type": card,
                        "prompt": f"What are the effects of the {card} card?"
                    }
                    return state
    return state

def deal_hands(state: dict):
    for p in PLAYERS:
        state['hands'][p] = []
        for _ in range(10):
            if state['deck']:
                state['hands'][p].append(state['deck'].pop())

def initial_state(seed: int | None = None) -> dict:
    rng = random.Random(seed)
    
    deck = []
    deck.extend(['tempura'] * 14)
    deck.extend(['sashimi'] * 14)
    deck.extend(['dumpling'] * 14)
    deck.extend(['maki_2'] * 12)
    deck.extend(['maki_3'] * 8)
    deck.extend(['maki_1'] * 6)
    deck.extend(['salmon_nigiri'] * 10)
    deck.extend(['squid_nigiri'] * 5)
    deck.extend(['egg_nigiri'] * 5)
    deck.extend(['pudding'] * 10)
    deck.extend(['wasabi'] * 6)
    deck.extend(['chopsticks'] * 4)
    
    rng.shuffle(deck)
    
    state = {
        TO_PLAY: PLAYERS[0],
        TURN: 1,
        PLY: 1,
        "round": 1,
        "deck": deck,
        "hands": {p: [] for p in PLAYERS},
        "tableaux": {p: [] for p in PLAYERS},
        "pending_plays": {},
        "scores": {p: 0 for p in PLAYERS},
        "puddings": {p: [] for p in PLAYERS},
        "discards": [],
        "catalog": {"effects": {}, "described": []}
    }
    
    deal_hands(state)
    return check_unknowns(state)

def resolve_unknown(state: dict, answer: dict) -> dict:
    new_state = copy.deepcopy(state)
    card_type = answer.get('card_type')
    if answer.get('unavailable'):
        new_state['catalog']['described'].append(card_type)
    else:
        new_state['catalog']['effects'][card_type] = answer.get('effects', [])
        new_state['catalog']['described'].append(card_type)
        
    if UNKNOWN in new_state:
        del new_state[UNKNOWN]
        
    return check_unknowns(new_state)

def legal_actions(state: dict) -> list[dict]:
    if is_terminal(state):
        return []
        
    p = state[TO_PLAY]
    hand = state['hands'][p]
    
    actions = []
    unique_cards = sorted(list(set(hand)))
    
    for card in unique_cards:
        actions.append({
            "type": "play",
            "cards": [card],
            LABEL: f"Play {card}"
        })
        
    if len(hand) >= 2:
        chopsticks_cards = [c for c in state['tableaux'][p] if is_chopsticks(c, state['catalog'])]
        if chopsticks_cards:
            c_card = sorted(chopsticks_cards)[0]
            pairs = set()
            for i in range(len(hand)):
                for j in range(i+1, len(hand)):
                    pairs.add(tuple(sorted([hand[i], hand[j]])))
                    
            for pair in sorted(list(pairs)):
                actions.append({
                    "type": "chopsticks",
                    "cards": list(pair),
                    "chopsticks_card": c_card,
                    LABEL: f"Use chopsticks to play {pair[0]} and {pair[1]}"
                })
                
    return actions

def score_round(state: dict):
    round_scores = {p: 0 for p in PLAYERS}

    # 1. Evaluate flat and multipliers
    for p in PLAYERS:
        active_mults = collections.defaultdict(list)
        for card in state['tableaux'][p]:
            cats = CATEGORIES.get(card, []) + [card]
            card_factor = 1
            for cat in cats:
                if active_mults[cat]:
                    card_factor = active_mults[cat].pop(0)
                    break
                    
            for eff in state['catalog']['effects'].get(card, []):
                if eff.get('op') == 'score_flat':
                    round_scores[p] += eff.get('points', 0) * card_factor
                elif eff.get('op') == 'multiply_next':
                    active_mults[eff.get('category')].append(eff.get('factor', 1))

    # 2. Evaluate sets and tiered
    for p in PLAYERS:
        counts = collections.Counter(state['tableaux'][p])
        for card_type, count in counts.items():
            for eff in state['catalog']['effects'].get(card_type, []):
                if eff.get('op') == 'score_per_set':
                    sets = count // eff.get('size', 1)
                    round_scores[p] += sets * eff.get('points', 0)
                elif eff.get('op') == 'score_tiered':
                    tiers = eff.get('tiers', [])
                    if count > 0 and tiers:
                        idx = min(count, len(tiers)) - 1
                        round_scores[p] += tiers[idx]

    # 3. Evaluate majority
    seen_majority_keys = set()
    majority_ops = []
    for p in PLAYERS:
        for card in state['tableaux'][p]:
            for eff in state['catalog']['effects'].get(card, []):
                if eff.get('op') == 'score_majority':
                    key = eff.get('count_field') or card
                    if key not in seen_majority_keys:
                        seen_majority_keys.add(key)
                        majority_ops.append((key, eff, card))
                        
    for key, eff, src_card in majority_ops:
        totals = {}
        for p in PLAYERS:
            if eff.get('count_field') == 'icons':
                totals[p] = sum(get_maki_icons(c) for c in state['tableaux'][p])
            else:
                totals[p] = state['tableaux'][p].count(src_card)
                
        sorted_totals = sorted(list(set(totals.values())), reverse=True)
        if not sorted_totals:
            continue
            
        highest = sorted_totals[0]
        if highest > 0:
            first_place = [p for p, t in totals.items() if t == highest]
            split = eff.get('first', 0) // len(first_place)
            for p in first_place:
                round_scores[p] += split
                
            if len(first_place) == 1 and len(sorted_totals) > 1:
                second_highest = sorted_totals[1]
                if second_highest > 0:
                    second_place = [p for p, t in totals.items() if t == second_highest]
                    split2 = eff.get('second', 0) // len(second_place)
                    for p in second_place:
                        round_scores[p] += split2
                        
    for p in PLAYERS:
        state['scores'][p] += round_scores[p]

def score_game_end(state: dict):
    seen_end_keys = set()
    end_ops = []
    for p in PLAYERS:
        for card in state['puddings'][p]:
            for eff in state['catalog']['effects'].get(card, []):
                if eff.get('op') == 'score_at_end':
                    key = eff.get('count_field') or card
                    if key not in seen_end_keys:
                        seen_end_keys.add(key)
                        end_ops.append((key, eff, card))
                        
    for key, eff, src_card in end_ops:
        totals = {p: state['puddings'][p].count(src_card) for p in PLAYERS}
        sorted_totals = sorted(list(set(totals.values())), reverse=True)
        if not sorted_totals:
            continue
            
        if len(sorted_totals) == 1:
            continue
            
        highest = sorted_totals[0]
        first_place = [p for p, t in totals.items() if t == highest]
        split = eff.get('first', 0) // len(first_place)
        for p in first_place:
            state['scores'][p] += split
            
        if eff.get('last') is not None and len(PLAYERS) > 2:
            lowest = sorted_totals[-1]
            last_place = [p for p, t in totals.items() if t == lowest]
            split_last = eff.get('last', 0) // len(last_place)
            for p in last_place:
                state['scores'][p] += split_last

def apply(state: dict, action: dict) -> dict:
    new_state = copy.deepcopy(state)
    p = new_state[TO_PLAY]
    
    new_state['pending_plays'][p] = action
    
    if p == PLAYERS[0]:
        new_state[TO_PLAY] = PLAYERS[1]
    else:
        for player in PLAYERS:
            act = new_state['pending_plays'][player]
            if act['type'] == 'play':
                card = act['cards'][0]
                new_state['hands'][player].remove(card)
                new_state['tableaux'][player].append(card)
            elif act['type'] == 'chopsticks':
                for c in act['cards']:
                    new_state['hands'][player].remove(c)
                    new_state['tableaux'][player].append(c)
                c_card = act['chopsticks_card']
                new_state['tableaux'][player].remove(c_card)
                new_state['hands'][player].append(c_card)
                
        new_state['pending_plays'] = {}
        new_state[TO_PLAY] = PLAYERS[0]
        
        h0 = new_state['hands'][PLAYERS[0]]
        h1 = new_state['hands'][PLAYERS[1]]
        new_state['hands'][PLAYERS[0]] = h1
        new_state['hands'][PLAYERS[1]] = h0
        
        if not new_state['hands'][PLAYERS[0]]:
            score_round(new_state)
            
            for player in PLAYERS:
                for card in new_state['tableaux'][player]:
                    if is_kept_for_end(card, new_state['catalog']):
                        new_state['puddings'][player].append(card)
                    else:
                        new_state['discards'].append(card)
                new_state['tableaux'][player] = []
                
            new_state['round'] += 1
            if new_state['round'] > 3:
                score_game_end(new_state)
            else:
                deal_hands(new_state)
                
        new_state[TURN] += 1
        
    new_state[PLY] += 1
    return check_unknowns(new_state)

def is_terminal(state: dict) -> bool:
    return state['round'] > 3

def winner(state: dict) -> str | None:
    if not is_terminal(state):
        raise ValueError("Game is not over")
        
    s0 = state['scores'][PLAYERS[0]]
    s1 = state['scores'][PLAYERS[1]]
    
    if s0 > s1:
        return PLAYERS[0]
    elif s1 > s0:
        return PLAYERS[1]
    else:
        p0 = len(state['puddings'][PLAYERS[0]])
        p1 = len(state['puddings'][PLAYERS[1]])
        if p0 > p1:
            return PLAYERS[0]
        elif p1 > p0:
            return PLAYERS[1]
        else:
            return None

def describe_state(state: dict, viewer: Viewer) -> str:
    lines = []
    lines.append(f"Round: {state['round']}, Turn: {state['turn']}, Ply: {state['ply']}")
    for p in PLAYERS:
        lines.append(f"{p} score: {state['scores'][p]}")
        lines.append(f"{p} tableau: {', '.join(state['tableaux'][p])}")
        lines.append(f"{p} puddings: {', '.join(state['puddings'][p])}")
        
        if p == 'automa':
            lines.append(f"{p} hand: {', '.join(state['hands'][p])}")
        else:
            if viewer == Viewer.HUMAN:
                lines.append(f"{p} hand: {', '.join(state['hands'][p])}")
            else:
                lines.append(f"{p} hand size: {len(state['hands'][p])}")
                
        if p in state['pending_plays']:
            lines.append(f"{p} has chosen a card.")
            
    unmodelled = [c for c in state['catalog']['described'] if c not in state['catalog']['effects']]
    if unmodelled:
        lines.append(f"Un-modelled cards: {', '.join(unmodelled)}")
        
    return '\n'.join(lines)

def check_invariants(state: dict) -> list[str]:
    errors = []
    total_cards = len(state['deck']) + len(state['discards'])
    for p in PLAYERS:
        total_cards += len(state['hands'][p])
        total_cards += len(state['tableaux'][p])
        total_cards += len(state['puddings'][p])
        
    if total_cards != 108:
        errors.append(f"Total cards is {total_cards}, expected 108")
        
    if state[TO_PLAY] not in PLAYERS:
        errors.append(f"Invalid TO_PLAY: {state[TO_PLAY]}")
        
    return errors